patches.diff:
From 9dd33768b3d348b61994aa0c21e5119c04df59b5 Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Tue, 24 Nov 2026 16:36:51 +0100
Subject: [PATCH] applets/kicker: add Turn Off Screen to the system actions
 model

Turning the screen off was only reachable through a keyboard shortcut.
Add a Turn Off Screen entry to the session actions, shown when DPMS is
supported, so Kicker, Kickoff and the dashboard can offer it as well.

BUG: 509314
---
 applets/kicker/CMakeLists.txt  |  3 ++-
 applets/kicker/systementry.cpp | 30 +++++++++++++++++++++++++++++-
 applets/kicker/systementry.h   |  7 +++++++
 applets/kicker/systemmodel.cpp |  1 +
 4 files changed, 39 insertions(+), 2 deletions(-)

diff --git a/applets/kicker/CMakeLists.txt b/applets/kicker/CMakeLists.txt
index b579d7b4da..e480c6f3ac 100644
--- a/applets/kicker/CMakeLists.txt
+++ b/applets/kicker/CMakeLists.txt
@@ -75,7 +75,8 @@ target_link_libraries(kickerplugin PRIVATE
                       KF6::Service
                       KF6::WindowSystem
                       Wayland::Client
-                      PW::KWorkspace)
+                      PW::KWorkspace
+                      KF6::ScreenDpms)

 qt_generate_wayland_protocol_client_sources(kickerplugin
     PRIVATE_CODE
diff --git a/applets/kicker/systementry.cpp b/applets/kicker/systementry.cpp
index 892f4fae93..85b6b6ad7e 100644
--- a/applets/kicker/systementry.cpp
+++ b/applets/kicker/systementry.cpp
@@ -13,11 +13,14 @@
 #include <KAuthorized>
 #include <KConfigGroup>
 #include <KLocalizedString>
+#include <KScreenDpms/Dpms>
 #include <KSharedConfig>
+#include <qnamespace.h>
 #include <sessionmanagement.h>

 int SystemEntry::s_instanceCount = 0;
 SessionManagement *SystemEntry::s_sessionManagement = nullptr;
+KScreen::Dpms *SystemEntry::s_kscreenDpms = nullptr;

 SystemEntry::SystemEntry(AbstractModel *owner, Action action)
     : AbstractEntry(owner)
@@ -52,6 +55,8 @@ SystemEntry::SystemEntry(AbstractModel *owner, const QString &id)
         m_action = Reboot;
     } else if (id == QLatin1String("shutdown")) {
         m_action = Shutdown;
+    } else if (id == QLatin1String("turn-off-screen")) {
+        m_action = TurnOffScreen;
     }

     refresh();
@@ -65,6 +70,7 @@ SystemEntry::~SystemEntry()

     if (!s_instanceCount) {
         delete std::exchange(s_sessionManagement, nullptr);
+        delete std::exchange(s_kscreenDpms, nullptr);
     }
 }

@@ -79,6 +85,9 @@ void SystemEntry::refresh()
         s_sessionManagement = new SessionManagement();
         QObject::connect(s_sessionManagement, &SessionManagement::stateChanged, this, &SystemEntry::sessionManagementStateChanged);
     }
+    if (!s_kscreenDpms) {
+        s_kscreenDpms = new KScreen::Dpms();
+    }

     bool valid = false;

@@ -123,6 +132,10 @@ void SystemEntry::refresh()
         QObject::connect(s_sessionManagement, &SessionManagement::canShutdownChanged, this, &SystemEntry::refresh);
         break;
     }
+    case TurnOffScreen:
+        valid = s_kscreenDpms->isSupported();
+        QObject::connect(s_kscreenDpms, &KScreen::Dpms::supportedChanged, this, &SystemEntry::refresh, Qt::UniqueConnection);
+        break;
     default:
         break;
     }
@@ -179,6 +192,9 @@ QString SystemEntry::iconName() const
     case Shutdown:
         return QStringLiteral("system-shutdown");
         break;
+    case TurnOffScreen:
+        return QStringLiteral("low-brightness");
+        break;
     default:
         break;
     }
@@ -213,6 +229,9 @@ QString SystemEntry::name() const
     case Shutdown:
         return i18n("Shut Down");
         break;
+    case TurnOffScreen:
+        return i18n("Turn Off Screen");
+        break;
     default:
         break;
     }
@@ -227,6 +246,7 @@ QString SystemEntry::group() const
     case LogoutSession:
     case SaveSession:
     case SwitchUser:
+    case TurnOffScreen:
         return i18n("Session");
     case Suspend:
     case Hibernate:
@@ -267,6 +287,9 @@ QString SystemEntry::description() const
     case Shutdown:
         return i18n("Turn off computer");
         break;
+    case TurnOffScreen:
+        return i18n("Turn off screen");
+        break;
     default:
         break;
     }
@@ -301,7 +324,9 @@ QString SystemEntry::id() const
     case Shutdown:
         return QStringLiteral("shutdown");
         break;
-
+    case TurnOffScreen:
+        return QStringLiteral("turn-off-screen");
+        break;
     default:
         break;
     }
@@ -343,6 +368,9 @@ bool SystemEntry::run(const QString &actionId, const QVariant &argument)
     case Shutdown:
         s_sessionManagement->requestShutdown();
         break;
+    case TurnOffScreen:
+        s_kscreenDpms->switchMode(KScreen::Dpms::Off);
+        break;
     default:
         break;
     }
diff --git a/applets/kicker/systementry.h b/applets/kicker/systementry.h
index c8988c8935..c67dc88f3b 100644
--- a/applets/kicker/systementry.h
+++ b/applets/kicker/systementry.h
@@ -10,6 +10,11 @@

 #include <QObject>

+namespace KScreen
+{
+class Dpms;
+}
+
 class SessionManagement;

 class SystemEntry : public QObject, public AbstractEntry
@@ -27,6 +32,7 @@ public:
         Hibernate,
         Reboot,
         Shutdown,
+        TurnOffScreen,
     };

     explicit SystemEntry(AbstractModel *owner, Action action);
@@ -67,4 +73,5 @@ private:

     static int s_instanceCount;
     static SessionManagement *s_sessionManagement;
+    static KScreen::Dpms *s_kscreenDpms;
 };
diff --git a/applets/kicker/systemmodel.cpp b/applets/kicker/systemmodel.cpp
index 7ea35b4bd5..f3f4f5d32a 100644
--- a/applets/kicker/systemmodel.cpp
+++ b/applets/kicker/systemmodel.cpp
@@ -124,6 +124,7 @@ void SystemModel::populate()
     addIfValid(SystemEntry::Hibernate);
     addIfValid(SystemEntry::Reboot);
     addIfValid(SystemEntry::Shutdown);
+    addIfValid(SystemEntry::TurnOffScreen);
 }

 #include "moc_systemmodel.cpp"
-- 
